/**
 * Interface representing temporary AWS credentials obtained through role assumption.
 * These credentials can be used to make AWS API calls with the assumed role's permissions.
 */
export interface AWSTempCredentials {
    accessKeyId: string;
    secretAccessKey: string;
    sessionToken: string;
}
/**
 * Obtains temporary AWS credentials by assuming a specified IAM role.
 *
 * IMPORTANT: The Lambda function's execution role must have permission to assume
 * the target role. In CDK, this is typically configured using:
 * ```typescript
 * // In the CDK stack where the target role is defined
 * targetRole.grantAssumeRole(lambdaFunction.role);
 * // or
 * targetRole.assumeRolePolicy.addStatements(new iam.PolicyStatement({
 *   effect: iam.Effect.ALLOW,
 *   principals: [new iam.ServicePrincipal('lambda.amazonaws.com')],
 *   actions: ['sts:AssumeRole']
 * }));
 * ```
 *
 * @param props - Configuration object containing:
 *   - roleArn: The ARN of the role to assume
 *   - roleSessionName: A unique identifier for this assumed role session
 * @returns Promise resolving to temporary AWS credentials (accessKeyId, secretAccessKey, sessionToken)
 * @throws Error if the role cannot be assumed due to missing permissions or other issues
 *
 * @example
 * ```typescript
 * const credentials = await getTempCredentials({
 *   roleArn: 'arn:aws:iam::123456789012:role/target-role',
 *   roleSessionName: 'my-lambda-session'
 * });
 *
 * // Use the credentials with AWS SDK v3
 * const s3Client = new S3Client({
 *   credentials: {
 *     accessKeyId: credentials.accessKeyId,
 *     secretAccessKey: credentials.secretAccessKey,
 *     sessionToken: credentials.sessionToken
 *   }
 * });
 * ```
 */
export declare function getTempCredentials(props: {
    roleArn: string;
    roleSessionName: string;
}): Promise<AWSTempCredentials>;
